describe('EditableCronComponent frequencies', () => {
  let component: EditableCronComponent;
  let changes: (string | null)[];

  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [EditableCronComponent, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
    });
    const fixture = TestBed.createComponent(EditableCronComponent);
    component = fixture.componentInstance;
    changes = [];
    component.registerOnChange((value: string | null) => changes.push(value));
    fixture.detectChanges();
  });

  afterEach(() => TestBed.resetTestingModule());

  it('builds the expression of each frequency', () => {
    component.patchState({ minute: 5, hour: 8, dayOfMonth: 3, month: 4 });

    const built = (['minute', 'hour', 'day', 'month', 'year'] as const).map((frequency) => {
      component.setFrequency(frequency);
      return component.expression();
    });

    expect(built).toEqual(['* * * * *', '5 * * * *', '5 8 * * *', '5 8 3 * *', '5 8 3 4 *']);
    expect(changes.at(-1)).toBe('5 8 3 4 *');
  });

  it('runs every day of the week without chosen weekdays', () => {
    component.setFrequency('week');
    expect(component.expression()).toBe('0 9 * * *');

    component.toggleWeekday(5);
    component.toggleWeekday(1);
    expect(component.expression()).toBe('0 9 * * 1,5');
    expect(component.isWeekdaySelected(1)).toBeTrue();

    component.toggleWeekday(1);
    expect(component.expression()).toBe('0 9 * * 5');
  });

  it('follows the custom expression only in custom mode', () => {
    component.customControl.setValue('*/5 * * * *');
    expect(component.state().customExpr).toBe('* * * * *');

    component.setFrequency('custom');
    component.customControl.setValue('*/5 * * * *');

    expect(component.expression()).toBe('*/5 * * * *');
    expect(component.nextRuns().length).toBe(5);
  });

  it('marks an invalid custom expression', () => {
    component.setFrequency('custom');
    component.customControl.setValue('not a cron');

    expect(component.validate(null)).toEqual({ cronInvalidExpression: true });
    expect(component.nextRuns()).toEqual([]);
  });

  it('shows a valid expression set from outside as custom', () => {
    (component as any).control.setValue('15 10 * * 1');

    expect(component.state().frequency).toBe('custom');
    expect(component.customControl.value).toBe('15 10 * * 1');
  });

  it('ignores an invalid expression set from outside', () => {
    (component as any).control.setValue('nonsense');

    expect(component.state().frequency).toBe('day');
  });

  it('pads the numbers of the selectors', () => {
    expect(component.pad(7)).toBe('07');
  });
});
